Do not provide any other text or markdown fences.

Here is the problem description:
<problem_description>
This is an easier version of the problem. In this version, $$$n \le 6$$$.Marek is working hard on creating strong testcases to his new algorithmic problem. You want to know what it is? Nah, we're not telling you. However, we can tell you how he generates the testcases.Marek chooses an integer $$$n$$$ and $$$n^2$$$ integers $$$p_{ij}$$$ ($$$1 \le i \le n$$$, $$$1 \le j \le n$$$). He then generates a random bipartite graph with $$$2n$$$ vertices. There are $$$n$$$ vertices on the left side: $$$\ell_1, \ell_2, \dots, \ell_n$$$, and $$$n$$$ vertices on the right side: $$$r_1, r_2, \dots, r_n$$$. For each $$$i$$$ and $$$j$$$, he puts an edge between vertices $$$\ell_i$$$ and $$$r_j$$$ with probability $$$p_{ij}$$$ percent.It turns out that the tests will be strong only if a perfect matching exists in the generated graph. What is the probability that this will occur?It can be shown that this value can be represented as $$$\frac{P}{Q}$$$ where $$$P$$$ and $$$Q$$$ are coprime integers and $$$Q \not\equiv 0 \pmod{10^9+7}$$$. Let $$$Q^{-1}$$$ be an integer for which $$$Q \cdot Q^{-1} \equiv 1 \pmod{10^9+7}$$$. Print the value of $$$P \cdot Q^{-1}$$$ modulo $$$10^9+7$$$.
</problem_description>

Here is the GNU C++17 code you have to repair:
<original_code>
#include <bits/stdc++.h>
#include <Modular.h>

using mod_t = Modular<1000000007>;

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    std::vector<mod_t> p(n * n);
    for (auto& x : p) {
        int v;
        std::cin >> v;
        x = mod_t(v) * mod_t(1) / 100;
    }

    int half = n / 2;
    std::vector<mod_t> f(1 << n);

    auto precomputeMask = [&]() {
        std::array<int, 64> m;
        int c = 0;
        for (int mask = 0; mask < 64; ++mask) {
            m[mask] = (__builtin_popcount(mask) == half) ? c++ : -1;
        }
        f.resize(1 << c);
        return m;
    };
    auto M = precomputeMask();

    auto run = [&](int start, int end, auto&& action) {
        int len = end - start;
        for (int edge = 0; edge < (1 << (len * n)); ++edge) {
            mod_t prob = 1;
            for (int i = start * n, t = edge; i < end * n; ++i, t >>= 1) {
                prob *= (t & 1) ? p[i] : (mod_t(1) - p[i]);
                if (prob == mod_t(0)) goto next_edge;
            }

            std::array<int, 6> idx{};
            int matchMask = 0;
            while (true) {
                int m = 0;
                bool ok = true;
                for (int k = 0; k < len; ++k) {
                    if (!(edge >> (k * n + idx[k]) & 1)) { ok = false; break; }
                    if (m & (1 << idx[k])) { ok = false; break; }
                    m |= 1 << idx[k];
                }
                if (!ok) goto next_idx;
                if (end == n) m ^= (1 << n) - 1;
                int pos = M[m];
                if (pos != -1) matchMask |= 1 << pos;

next_idx:
                int j = len - 1;
                while (j >= 0 && idx[j] == n - 1) {
                    idx[j] = 0;
                    --j;
                }
                if (j < 0) break;
                ++idx[j];
            }

            action(matchMask, prob);
next_edge:;
        }
    };

    run(0, half, [&](int s, mod_t v) { f[s] += v; });
    for (int step = 1; step < (int)f.size(); step <<= 1) {
        for (int i = 0; i < (int)f.size(); ++i) {
            if (!(i & step)) f[i | step] += f[i];
        }
    }

    mod_t ans{};
    run(half, n, [&](int s, mod_t v) {
        ans += v * (f.back() - f[((1 << n) - 1) ^ s]);
    });
    std::cout << (int)ans << '\n';
}
</original_code>
